import sys

def solve(u, v):
    if u == 0 and v == 0:
        return "0\n"

    if u > v:
        return "-1\n"

    result = []
    current_sum = 0

    # Try to use the largest possible number that fits the criteria
    while u > 0:
        bit_position = u.bit_length() - 1
        value = 1 << bit_position
        if current_sum + value <= v:
            result.append(value)
            current_sum += value
            u ^= value
        else:
            break

    if u == 0:
        remaining = v - current_sum
        if remaining > 0:
            result.append(remaining)
        return f"{len(result)}\n" + " ".join(map(str, result)) + "\n"

    return "-1\n"

def main():
    import sys
    input = sys.stdin.read().strip()
    u, v = map(int, input.split())
    print(solve(u, v), end="")

if __name__ == "__main__":
    main()
